    indexerTaskStatsProvider = new IndexerTaskCountStatsProvider()
    {
      @Override
      public Map<String, Long> getWorkerRunningTasks()
      {
        return ImmutableMap.of(
            "wikipedia", 2L,
            "animals", 3L
        );
